class Rental:
    ADMIN_FEE = 4
    def pay(self, hours):
        if hours <= 5:
            return self.ADMIN_FEE
        return 0

class Rental:
    ADMIN_FEE = 4
    def pay(self, hours):
        if hours <= 5:
            return self.ADMIN_FEE
        return 0

class PoweredRental(Rental):
    HOURLY_FEE = 3
    def pay(self, hours):
        return super().pay(hours) + self.HOURLY_FEE * hours
